  private setupKeyboardShortcuts(): void {
    const buttonActions = [
      () => this.startGame(),
      () => this.restartGame(),
      () => this.toggleMute(),
      () => this.openControlsModal(),
    ];

    const buttonCoords = [
      { x: 480, y: 332, w: 308 },
      { x: 480, y: 384, w: 308 },
      { x: 360, y: 436, w: 188 },
      { x: 580, y: 436, w: 228 },
    ];

    const updateCanvasFocus = (idx: number): void => {
      this.focusedButtonIndex = idx;
      if (!this.canvasFocusBox) return;
      if (idx < 0 || idx >= buttonCoords.length) {
        this.canvasFocusBox.setVisible(false);
      } else {
        const c = buttonCoords[idx];
        this.canvasFocusBox.setPosition(c.x, c.y).setSize(c.w, 52).setVisible(true);
      }
    };

    this.keydownHandler = (event: KeyboardEvent): void => {
      // Phím Escape đóng hộp thoại nếu đang mở
      if (event.key === 'Escape') {
        if (this.isModalOpen) {
          event.preventDefault();
          this.closeControlsModal();
        }
        return;
      }

      if (this.isModalOpen) {
        if (event.key === 'Tab') {
          const focusable = Array.from(document.querySelectorAll<HTMLElement>(
            '#controls-modal button, #controls-modal input, #controls-modal select'));
          const first = focusable[0];
          const last = focusable[focusable.length - 1];
          if (event.shiftKey && (document.activeElement === first || !focusable.includes(document.activeElement as HTMLElement))) {
            event.preventDefault();
            last?.focus();
          } else if (!event.shiftKey && (document.activeElement === last || !focusable.includes(document.activeElement as HTMLElement))) {
            event.preventDefault();
            first?.focus();
          }
        }
        return;
      }
      if (event.key === 'Tab') { updateCanvasFocus(-1); return; }

      // Phím tắt M: bật/tắt nhanh âm thanh
      if (event.key === 'm' || event.key === 'M') {
        event.preventDefault();
        this.toggleMute();
        return;
      }

      // Phím tắt H hoặc C: mở/đóng hướng dẫn
      if (event.key === 'h' || event.key === 'H' || event.key === 'c' || event.key === 'C') {
        event.preventDefault();
        this.openControlsModal();
        return;
      }

      // Điều hướng tiêu điểm trên Canvas bằng phím mũi tên / Tab
      if (event.key === 'ArrowDown') {
        // Chỉ chặn tab nếu tiêu điểm đang không ở trong các nút HTML
        const isDomFocused = document.activeElement && document.activeElement !== document.body && document.activeElement.tagName === 'BUTTON';
        if (!isDomFocused) {
          event.preventDefault();
          const next = (this.focusedButtonIndex + 1) % buttonActions.length;
          updateCanvasFocus(next);
        }
      } else if (event.key === 'ArrowUp') {
        const isDomFocused = document.activeElement && document.activeElement !== document.body && document.activeElement.tagName === 'BUTTON';
        if (!isDomFocused) {
          event.preventDefault();
          const prev = this.focusedButtonIndex <= 0 ? buttonActions.length - 1 : this.focusedButtonIndex - 1;
          updateCanvasFocus(prev);
        }
      } else if (event.key === 'Enter' || event.key === ' ') {
        if (this.focusedButtonIndex >= 0 && this.focusedButtonIndex < buttonActions.length) {
          const isDomFocused = document.activeElement && document.activeElement.tagName === 'BUTTON';
          if (!isDomFocused) {
            event.preventDefault();
            buttonActions[this.focusedButtonIndex]();
          }
        }
      }
    };

    window.addEventListener('keydown', this.keydownHandler);
  }

  private cleanup(): void {
    if (this.keydownHandler) {
      window.removeEventListener('keydown', this.keydownHandler);
      this.keydownHandler = undefined;
    }
    if (this.domLayer) {
      this.domLayer.remove();
      this.domLayer = null;
    }
  }
}
import Phaser from 'phaser';
import { UI_DEPTH } from '../../data/config';

type Action = 'attack' | 'dodge' | 'earth' | 'flame' | 'water' | 'fourth' | 'interact';

export class TouchControls {
  readonly direction = new Phaser.Math.Vector2();
  private activePointerId: number | null = null;
  private joystickKnob: Phaser.GameObjects.Arc;
  private readonly origin = new Phaser.Math.Vector2(109, 421);

  constructor(private scene: Phaser.Scene, private perform: (action: Action) => void,
    private enabled: () => boolean) {
    const back = scene.add.circle(this.origin.x, this.origin.y, 70, 0xf2e2b7, 0.13)
      .setStrokeStyle(2, 0xe0d8a5, 0.50).setDepth(UI_DEPTH);
    back.setInteractive();
    this.joystickKnob = scene.add.circle(this.origin.x, this.origin.y, 29, 0xd7be84, 0.45)
      .setStrokeStyle(2, 0xffeac1, 0.8).setDepth(UI_DEPTH + 1).setInteractive();
    const begin = (pointer: Phaser.Input.Pointer): void => {
      if (!enabled() || this.activePointerId !== null) return;
      this.activePointerId = pointer.id;
      this.updateJoystick(pointer);
    };
    back.on('pointerdown', begin);
    this.joystickKnob.on('pointerdown', begin);
    const move = (pointer: Phaser.Input.Pointer): void => {
      if (pointer.id === this.activePointerId) this.updateJoystick(pointer);
    };
    scene.input.on('pointermove', move);
    const reset = (): void => {
      this.activePointerId = null;
      this.direction.set(0, 0);
      this.joystickKnob.setPosition(this.origin.x, this.origin.y);
    };
    const release = (pointer: Phaser.Input.Pointer): void => {
      if (pointer.id === this.activePointerId) reset();
    };
    scene.input.on('pointerup', release);
    scene.input.on('pointercancel', release);
    scene.game.events.on('blur', reset);
    document.addEventListener('visibilitychange', reset);
    scene.events.once('shutdown', () => {
      scene.input.off('pointermove', move);
      scene.input.off('pointerup', release);
      scene.input.off('pointercancel', release);
      scene.game.events.off('blur', reset);
      document.removeEventListener('visibilitychange', reset);
      reset();
    });
    this.makeButton(847, 430, 49, 'CHÉM', 'attack', 0xc4744c);
    this.makeButton(745, 464, 35, 'NÉ', 'dodge', 0x507c7d);
    this.makeButton(780, 354, 35, 'Q', 'earth', 0x877349);
    this.makeButton(891, 351, 35, 'E', 'flame', 0x9d5a37);
    this.makeButton(780, 276, 32, 'R', 'water', 0x397f99);
    this.makeButton(891, 276, 32, 'T', 'fourth', 0x66558a);
    this.makeButton(656, 467, 32, 'F', 'interact', 0x777b66);
  }

  private makeButton(x: number, y: number, radius: number, title: string,
    action: Action, fill: number): void {
    const shape = this.scene.add.circle(x, y, radius, fill, 0.74)
      .setStrokeStyle(2, 0xece0c2, 0.85).setDepth(UI_DEPTH).setInteractive();
    const text = this.scene.add.text(x, y, title, {
      fontFamily: 'Arial, sans-serif', fontSize: `${radius > 42 ? 15 : 16}px`,
      fontStyle: 'bold', color: '#fff5d9',
    }).setOrigin(0.5).setDepth(UI_DEPTH + 1).setInteractive();
    const down = (): void => {
      if (!this.enabled()) return;
      this.perform(action);
      this.scene.tweens.add({ targets: [shape, text], scale: 0.90, yoyo: true, duration: 85 });
    };
    shape.on('pointerdown', down);
    text.on('pointerdown', down);
  }

  private updateJoystick(pointer: Phaser.Input.Pointer): void {
    const dx = pointer.x - this.origin.x;
    const dy = pointer.y - this.origin.y;
    const length = Math.hypot(dx, dy);
    if (length < 7) {
      this.direction.set(0, 0);
      return;
    }
    const magnitude = Math.min(1, length / 55);
    this.direction.set(dx / length * magnitude, dy / length * magnitude);
    this.joystickKnob.setPosition(this.origin.x + this.direction.x * 39,
      this.origin.y + this.direction.y * 39);
  }
}
export const DIRECTIONS = ['down', 'left', 'right', 'up'] as const;
export type SpriteDirection = typeof DIRECTIONS[number];
export interface SpritePose { readonly start: number; readonly count: number; readonly frameRate: number; readonly repeat: number; }
export interface SpriteSheet { readonly size: number; readonly columns: number; readonly atlasColumns?: number; readonly feet: number; readonly poses: Readonly<Record<string, SpritePose>>; }

function poses(definitions: readonly (readonly [string, number, number, number])[]): Readonly<Record<string, SpritePose>> {
  return Object.freeze(Object.fromEntries(definitions.map(([name, count, frameRate, repeat], index) => [name, Object.freeze({
    start: definitions.slice(0, index).reduce((total, entry) => total + entry[1], 0), count, frameRate, repeat,
  })])));
}
const hero = poses([
  ['idle', 4, 6, -1], ['walk', 6, 9, -1], ['run', 6, 14, -1],
  ['attack1', 5, 18, 0], ['attack2', 5, 18, 0], ['attack3', 6, 18, 0],
  ['dodge', 4, 16, 0], ['hit', 3, 14, 0], ['death', 6, 18, 0],
  ['earth', 5, 12, 0], ['fire', 5, 12, 0], ['water', 5, 12, 0],
  ['victory', 4, 8, 0], ['interaction', 4, 8, 0],
]);
const enemy = poses([['idle', 4, 5, -1], ['walk', 6, 8, -1], ['attack', 5, 14, 0], ['hit', 3, 14, 0], ['death', 6, 24, 0]]);
const boss = poses([['idle', 4, 5, -1], ['walk', 6, 8, -1], ['windup', 4, 10, 0], ['attack', 6, 14, 0], ['hit', 3, 14, 0], ['death', 6, 12, 0], ['transition', 4, 8, 0]]);
export const SPRITE_MANIFEST: Readonly<Record<'hero' | 'hero_axe' | 'hero_sword' | 'moctinh' | 'matroi' | 'hoyer' | 'wolf' | 'spider' | 'thuongluong' | 'thachtuong' | 'hacan', SpriteSheet>> = Object.freeze({
  hero: Object.freeze({ size: 48, columns: 68, atlasColumns: 42, feet: 42, poses: hero }),
  hero_axe: Object.freeze({ size: 48, columns: 68, atlasColumns: 42, feet: 42, poses: hero }),
  hero_sword: Object.freeze({ size: 48, columns: 68, atlasColumns: 42, feet: 42, poses: hero }),
  moctinh: Object.freeze({ size: 48, columns: 24, feet: 42, poses: enemy }),
  matroi: Object.freeze({ size: 32, columns: 24, feet: 28, poses: enemy }),
  hoyer: Object.freeze({ size: 96, columns: 24, atlasColumns: 21, feet: 84, poses: enemy }),
  wolf: Object.freeze({ size: 48, columns: 24, feet: 42, poses: enemy }),
  spider: Object.freeze({ size: 48, columns: 24, feet: 42, poses: enemy }),
  thuongluong: Object.freeze({ size: 96, columns: 33, atlasColumns: 21, feet: 84, poses: boss }),
  thachtuong: Object.freeze({ size: 96, columns: 33, atlasColumns: 21, feet: 84, poses: boss }),
  hacan: Object.freeze({ size: 96, columns: 33, atlasColumns: 21, feet: 84, poses: boss }),
});
export type SpriteName = keyof typeof SPRITE_MANIFEST;

export function animationFrames(name: SpriteName, state: string, direction: SpriteDirection): number[] {
  const sheet = SPRITE_MANIFEST[name];
  const pose = sheet.poses[state];
  if (!pose || !DIRECTIONS.includes(direction)) throw new Error('Unknown sprite pose or direction');
  return Array.from({ length: pose.count }, (_, index) => DIRECTIONS.indexOf(direction) * sheet.columns + pose.start + index);
}
export function facingDirection(horizontal: number, vertical: number): SpriteDirection {
  return Math.abs(horizontal) > Math.abs(vertical) ? horizontal < 0 ? 'left' : 'right' : vertical < 0 ? 'up' : 'down';
}
export function canPlayLocomotion(state: string, playing: boolean): boolean {
  return state !== 'death' && (!playing || state === 'idle' || state === 'walk' || state === 'run');
}
