export class Player {
  readonly view: Phaser.GameObjects.Container;
  readonly direction = new Phaser.Math.Vector2(1, 0);
  readonly controls: TouchControls;
  private sprite: Phaser.GameObjects.Sprite | null = null;
  private visualState = 'idle';
  private keys: Record<string, Phaser.Input.Keyboard.Key> | null = null;
  private attackAt = 0;
  private lastAttack = -3000;
  private combo = 0;
  private dodgeReadyAt = 0;
  private dodgeEndAt = 0;
  private invulnerableUntil = 0;
  private shieldRemainingMs = 0;
  private skillInvulnerabilityMs = 0;
  private readonly statusPresentation: PlayerStatusPresentation;
  private readonly equipmentPresentation: PlayerEquipmentPresentation;
  private locked: () => boolean;

  constructor(private scene: Phaser.Scene, x: number, y: number,
    private actions: PlayerActions, locked: () => boolean,
    private readonly barriers: readonly Barrier[] = []) {
    this.locked = locked;

    if (scene.textures.exists(SPRITE_KEYS.hero)) {
      const shadow = scene.add.ellipse(0, 16, 36, 12, 0x112b26, 0.65);
      this.sprite = scene.add.sprite(0, -6, SPRITE_KEYS.hero, 0);
      this.playPose('idle');
      const name = label(scene, 0, -38, 'THIÊN MỆNH', 13, '#fff5d2', 'center');
      this.view = scene.add.container(x, y, [shadow, this.sprite, name]);
      this.view.setDepth(30 + y / 10);
    } else {
      this.view = actor(scene, x, y, 0x4d8db1, 'THIÊN MỆNH', 22, true);
    }

    this.statusPresentation = new PlayerStatusPresentation(scene, this.view);
    this.equipmentPresentation = new PlayerEquipmentPresentation(scene, this.view);
    this.syncEquipmentPresentation();

    if (scene.input.keyboard) {
      this.keys = scene.input.keyboard.addKeys({
        up: 'W', down: 'S', left: 'A', right: 'D',
        up2: 'UP', down2: 'DOWN', left2: 'LEFT', right2: 'RIGHT',
        attack: 'J', dodge: 'SPACE', earth: 'Q', flame: 'E', water: 'R', fourth: 'T', interact: 'F',
      }) as Record<string, Phaser.Input.Keyboard.Key>;
    }
    this.controls = new TouchControls(scene, (action) => {
      if (action === 'attack') this.attack();
      if (action === 'dodge') this.dodge();
      if (action === 'earth') this.earth();
      if (action === 'flame') this.flame();
      if (action === 'water') this.useSkill('slot-3');
      if (action === 'fourth') this.useSkill('slot-4');
      if (action === 'interact') { this.playPose('interaction'); this.actions.interact(); }
    }, () => !this.isLocked);
  }

  get x(): number { return this.view.x; }
  get y(): number { return this.view.y; }
  get isDodging(): boolean { return this.scene.time.now < this.dodgeEndAt; }
  get isDead(): boolean { return this.visualState === 'death'; }
  get canBeHit(): boolean { return this.visualState !== 'death' && this.skillInvulnerabilityMs <= 0 && this.scene.time.now >= this.invulnerableUntil; }
  private get isLocked(): boolean { return this.isDead || this.locked(); }

  update(delta: number): void {
    if (this.isLocked) { this.syncStatusPresentation(); this.syncEquipmentPresentation(); return; }
    this.shieldRemainingMs = Math.max(0, this.shieldRemainingMs - delta);
    this.skillInvulnerabilityMs = Math.max(0, this.skillInvulnerabilityMs - delta);
    const time = this.scene.time.now;
    const key = this.keys;
    if (key) {
      if (Phaser.Input.Keyboard.JustDown(key.attack)) this.attack();
      if (Phaser.Input.Keyboard.JustDown(key.dodge)) this.dodge();
      if (Phaser.Input.Keyboard.JustDown(key.earth)) this.earth();
      if (Phaser.Input.Keyboard.JustDown(key.flame)) this.flame();
      if (Phaser.Input.Keyboard.JustDown(key.water)) this.useSkill('slot-3');
      if (Phaser.Input.Keyboard.JustDown(key.fourth)) this.useSkill('slot-4');
      if (Phaser.Input.Keyboard.JustDown(key.interact)) { this.playPose('interaction'); this.actions.interact(); }
    }
    let vx = (Number(Boolean(key?.right.isDown || key?.right2.isDown)) -
      Number(Boolean(key?.left.isDown || key?.left2.isDown)));
    let vy = (Number(Boolean(key?.down.isDown || key?.down2.isDown)) -
      Number(Boolean(key?.up.isDown || key?.up2.isDown)));
    vx += this.controls.direction.x;
    vy += this.controls.direction.y;
    const length = Math.hypot(vx, vy);
    if (length > 0.08 && !this.isDodging) this.direction.set(vx / length, vy / length);
    const moving = length > 0.08 || this.isDodging;
    const speed = this.isDodging ? 540 : getPlayerStats(gameState.data).speed;
    const moveDirX = this.isDodging ? this.direction.x : length ? vx / length : 0;
    const moveDirY = this.isDodging ? this.direction.y : length ? vy / length : 0;
    const next = moveInWorld({ x: this.view.x, y: this.view.y }, {
      x: this.view.x + moveDirX * speed * delta / 1000,
      y: this.view.y + moveDirY * speed * delta / 1000,
    }, 22, this.barriers);
    this.view.setPosition(next.x, next.y);
    this.view.setDepth(30 + this.view.y / 10);
    this.syncStatusPresentation();
    if (this.sprite) {
      if (time > this.attackAt && canPlayLocomotion(this.visualState, this.sprite.anims.isPlaying)) {
        this.playPose(this.isDodging || length > 0.75 ? 'run' : moving ? 'walk' : 'idle');
      }
    }
    if (!this.sprite) this.view.setScale(this.isDodging ? 0.89 : 1 + (moving ? Math.sin(time / 80) * 0.04 : 0));
    const s = gameState.data;
    s.mp = Math.min(getPlayerStats(s).maxMp, s.mp + delta / 1000 * 7.5);
    this.syncEquipmentPresentation();
  }

  getEquippedWeapon(): WeaponDefinition {
    const weaponId = gameState.data.rpg?.equipment?.slots?.weapon;
    return getEquippedWeaponOrDefault(weaponId, gameState.data.level);
  }

  private syncStatusPresentation(): void {
    if (this.isDead) this.statusPresentation?.destroy();
    else this.statusPresentation?.sync(this.shieldRemainingMs, this.skillInvulnerabilityMs);
  }

  private syncEquipmentPresentation(): void {
    this.equipmentPresentation?.sync(this.sprite, gameState.data.rpg?.equipment?.slots ?? {});
  }

  private playPose(state: string, durationMs?: number): void {
    if (!this.sprite || (this.visualState === 'death' && state !== 'death')) return;
    const type = this.getEquippedWeapon().weaponType;
    const requested = type === 'axe' ? 'hero_axe' : type === 'sword' ? 'hero_sword' : 'hero';
    const direction = facingDirection(this.direction.x, this.direction.y);
    const name = ([requested, 'hero'] as const).find(candidate =>
      this.scene.textures.exists(SPRITE_KEYS[candidate])
      && this.scene.anims.exists(candidate + '_' + state + '_' + direction)
      && animationFrames(candidate, state, direction).every(frame =>
        this.scene.textures.get(SPRITE_KEYS[candidate]).has(String(frame))));
    if (!name) return;
    if (this.sprite.texture?.key !== SPRITE_KEYS[name]) {
      this.sprite.setTexture(SPRITE_KEYS[name]);
    }
    this.visualState = state;
    this.sprite.setFlipX(false).play(name + '_' + state + '_' + direction, true);
    const pose = SPRITE_MANIFEST.hero.poses[state];
    this.sprite.anims.timeScale = durationMs ? pose.count * 1000 / pose.frameRate / durationMs : 1;
    this.syncEquipmentPresentation();
  }

  attack(): void {
    if (this.isLocked) return;
    const time = this.scene.time.now;
    if (time < this.attackAt || this.isDodging) return;
    this.combo = time - this.lastAttack <= BALANCE.comboWindowMs ? (this.combo % 3) + 1 : 1;
    this.lastAttack = time;
    const weapon = this.getEquippedWeapon();
    this.attackAt = time + calculateWeaponAttackTiming(weapon, this.combo);
    if (this.sprite) {
      this.playPose('attack' + this.combo, this.attackAt - time);
    }
    this.actions.basic(this.combo, this.direction.clone());
  }

  dodge(): void {
    const time = this.scene.time.now;
    if (this.isLocked || time < this.dodgeReadyAt) return;
    this.dodgeReadyAt = time + BALANCE.dodgeCooldownMs;
    this.dodgeEndAt = time + BALANCE.dodgeDurationMs;
    this.invulnerableUntil = this.dodgeEndAt + 60;
    this.playPose('dodge', BALANCE.dodgeDurationMs);
    audioManager.playCue('dodge', { priority: 1 });
    floatText(this.scene, this.x, this.y - 34, 'LƯỚT', '#d0f0ea');
  }

  earth(): void {
    this.useSkill('slot-1');
  }

  flame(): void {
    this.useSkill('slot-2');
  }

  useSkill(slot: SkillSlot): void {
    const s = gameState.data;
    if (this.isLocked) return;
    const result = castEquippedSkill(s.rpg.skills, {
      level: s.level, hp: s.hp, mp: s.mp, maxHp: getPlayerStats(s).maxHp, maxMp: getPlayerStats(s).maxMp,
      attack: s.attack, gold: s.gold, equippedWeaponId: s.rpg.equipment.slots.weapon,
    }, slot, Date.now());
    if (!result.success || !result.skill) {
      floatText(this.scene, this.x, this.y - 40, result.reason === 'on_cooldown' ? 'ĐANG HỒI CHIÊU' : 'CHƯA THỂ DÙNG', '#ffce91');
      return;
    }
    gameState.data = { ...s, hp: result.caster.hp, mp: result.caster.mp, rpg: { ...s.rpg, skills: result.progress } };
    const effect = result.skill.effect;
    if (effect.statusEffect === 'shield') this.shieldRemainingMs = effect.statusDurationMs ?? 0;
    if (effect.statusEffect === 'invulnerable') this.skillInvulnerabilityMs = effect.statusDurationMs ?? 0;
    this.syncStatusPresentation();
    gameState.save();
    this.playPose(result.skill.element === 'flame' ? 'fire' : result.skill.element === 'water' ? 'water' : 'earth');
    floatText(this.scene, this.x, this.y - 40, result.skill.vietnameseName, '#a4e6e3');
    this.actions.skill(result.skill, result.damageDealt ?? 0, this.direction.clone());
  }

  hit(damage: number): void {
    if (!this.canBeHit) return;
    if (this.shieldRemainingMs > 0) damage = Math.max(1, Math.round(damage / 2));
    const s = gameState.data;
    audioManager.playCue('player_hurt', { priority: 2 });
    s.hp = Math.max(0, s.hp - damage);
    this.invulnerableUntil = this.scene.time.now + 550;
    floatText(this.scene, this.x, this.y - 45, `-${damage}`, '#ff827c');
    if (graphicsSettings.getBudget().cameraShake) this.scene.cameras.main.shake(85, 0.0025);
    this.playPose(s.hp <= 0 ? 'death' : 'hit');
    if (s.hp <= 0) {
      this.statusPresentation?.destroy();
      const pose = SPRITE_MANIFEST.hero.poses.death;
      this.actions.dead(this.sprite ? pose.count * 1000 / pose.frameRate : 0);
    } else {
      this.scene.tweens.add({ targets: this.view, alpha: 0.33, yoyo: true, repeat: 2, duration: 85,
        onComplete: () => this.view.setAlpha(1) });
    }
  }
}
import Phaser from 'phaser';
import { Enemy } from '../entities/Enemy';
import { Player } from '../entities/Player';
import { gameState } from './GameState';
import { BossSystem } from './BossSystem';
import { audioManager } from '../audio/AudioManager';
import { graphicsSettings } from '../rendering/GraphicsSettings';
import type { SkillDefinition } from '../../data/skills';
import { skillHitsTarget } from './SkillCombat';
import {
  calculateWeaponDamage,
  calculateWeaponKnockback,
  getEquippedWeaponOrDefault,
  type WeaponDefinition,
} from '../../data/weapons';

export class CombatSystem {
  constructor(private scene: Phaser.Scene, private enemies: () => Enemy[], private bossSystem?: BossSystem) {}

  basic(player: Player, combo: number, dir: Phaser.Math.Vector2): void {
    const s = gameState.data;
    const weaponId = s.rpg?.equipment?.slots?.weapon;
    const weapon = getEquippedWeaponOrDefault(weaponId, s.level);
    const comboIndex = Math.max(0, combo - 1);
    const isCritical = Math.random() < weapon.criticalChance;
    const base = calculateWeaponDamage(weapon, comboIndex, s.attack, isCritical);
    const reach = weapon.range;
    const knockback = calculateWeaponKnockback(weapon, comboIndex);

    this.slashEffect(player.x, player.y, dir, combo, weapon);
    audioManager.playCue('sword_slash', { pitchMultiplier: 1 + combo * 0.04 });
    let hit = 0;
    for (const enemy of this.enemies()) {
      if (!enemy.isAlive) continue;
      const dx = enemy.x - player.x;
      const dy = enemy.y - player.y;
      const distance = Math.hypot(dx, dy);
      const dot = distance ? (dx * dir.x + dy * dir.y) / distance : 1;
      if (distance <= reach + enemy.radius && dot >= (combo === 3 ? -0.12 : 0.19)) {
        enemy.damage(base, dir.x * knockback, dir.y * knockback);
        hit++;
      }
    }
    const boss = this.bossSystem?.boss;
    if (boss?.isAlive) {
      const dx = boss.x - player.x;
      const dy = boss.y - player.y;
      const distance = Math.hypot(dx, dy);
      const dot = distance ? (dx * dir.x + dy * dir.y) / distance : 1;
      if (distance <= reach + boss.radius && dot >= (combo === 3 ? -0.12 : 0.19)) {
        this.bossSystem?.damageBoss(base, dir.x * knockback, dir.y * knockback);
        hit++;
      }
    }
    if (hit) {
      audioManager.playCue('hit_impact', { volume: 0.75, priority: 1 });
      const shakeIntensity = combo === 3 ? (weapon.knockback >= 30 ? 0.004 : 0.003) : 0.0015;
      if (graphicsSettings.getBudget().cameraShake) this.scene.cameras.main.shake(combo === 3 ? 80 : 50, shakeIntensity);
    }
  }

  skill(player: Player, skill: SkillDefinition, damage: number, direction: Phaser.Math.Vector2): void {
    this.skillEffect(player.x, player.y, skill, direction);
    audioManager.playCue(skill.element === 'flame' ? 'skill_flame' : 'skill_earth', { priority: 2 });
    if (damage <= 0) return;
    for (const enemy of this.enemies()) {
      if (!enemy.isAlive || !skillHitsTarget(skill, player, direction, enemy)) continue;
      const offsetX = enemy.x - player.x;
      const offsetY = enemy.y - player.y;
      const length = Math.max(1, Math.hypot(offsetX, offsetY));
      enemy.damage(damage, offsetX / length * (skill.effect.knockback ?? 0), offsetY / length * (skill.effect.knockback ?? 0));
      enemy.applyStatus(skill.effect.statusEffect, skill.effect.statusDurationMs ?? 0, damage);
    }
    const boss = this.bossSystem?.boss;
    if (boss?.isAlive && skillHitsTarget(skill, player, direction, boss)) {
      this.bossSystem?.damageBoss(damage, direction.x * (skill.effect.knockback ?? 0), direction.y * (skill.effect.knockback ?? 0));
    }
    if (graphicsSettings.getBudget().cameraShake) this.scene.cameras.main.shake(100, 0.003);
  }

  private slashEffect(x: number, y: number, dir: Phaser.Math.Vector2, combo: number, weapon?: WeaponDefinition): void {
    const g = this.scene.add.graphics().setPosition(x, y).setDepth(900);
    const centerAngle = Math.atan2(dir.y, dir.x);
    const spread = combo === 3 ? 1.45 : 1.12;
    const start = centerAngle - spread;
    const end = centerAngle + spread;
    const reach = weapon?.range ?? 92;
    const heavy = combo === 3;
    const width = heavy ? 18 : 12;
    const color = weapon?.weaponType === 'axe' ? 0xc87939 : weapon?.weaponType === 'spear' ? 0xd9ad61 : 0xd4b887;
    this.meleeFootprint(g, centerAngle, reach, combo, color);
    g.lineStyle(width, color, 0.55);
    if (weapon?.weaponType === 'spear') {
      const sideX = -Math.sin(centerAngle) * (heavy ? 7 : 4);
      const sideY = Math.cos(centerAngle) * (heavy ? 7 : 4);
      const baseX = Math.cos(centerAngle) * reach * 0.65;
      const baseY = Math.sin(centerAngle) * reach * 0.65;
      g.lineStyle(heavy ? 9 : 5, color, 0.8);
      g.lineBetween(0, 0, baseX, baseY);
      g.fillStyle(0xffeed0, 0.95);
      g.fillTriangle(baseX + sideX, baseY + sideY, Math.cos(centerAngle) * reach,
        Math.sin(centerAngle) * reach, baseX - sideX, baseY - sideY);
    } else {
      const radius = reach - width / 2;
      g.beginPath();
      g.arc(0, 0, radius, start, end, false);
      g.strokePath();
      g.lineStyle(heavy ? 6 : 4, 0xffeed0, 0.95);
      g.beginPath();
      g.arc(0, 0, reach - 3, start, end, false);
      g.strokePath();
      if (weapon?.weaponType === 'axe') {
        g.fillStyle(color, 0.55);
        g.beginPath();
        g.arc(0, 0, reach - 3, centerAngle - 0.65, end, false);
        g.arc(0, 0, reach * 0.52, end, centerAngle - 0.65, true);
        g.closePath();
        g.fillPath();
      }
    }
    this.effectSparks(x + Math.cos(centerAngle) * reach, y + Math.sin(centerAngle) * reach, color);
    this.finishEffect(g, 185);
  }

  private meleeFootprint(g: Phaser.GameObjects.Graphics, angle: number, reach: number, combo: number, color: number): void {
    const spread = Math.acos(combo === 3 ? -0.12 : 0.19);
    g.lineStyle(1, color, 0.25);
    g.beginPath();
    g.moveTo(0, 0);
    g.arc(0, 0, reach, angle - spread, angle + spread, false);
    g.closePath();
    g.strokePath();
  }

  private skillEffect(x: number, y: number, skill: SkillDefinition, direction: Phaser.Math.Vector2): void {
    const color = skill.element === 'water' ? 0x7ccbdc : skill.element === 'flame' ? 0xffa04e
      : skill.element === 'earth' ? 0xd4af37 : 0xe8dcc3;
    const g = this.scene.add.graphics().setPosition(x, y).setDepth(850);
    g.lineStyle(3, color, 0.9);
    g.fillStyle(color, 0.3);
    if (skill.targetType === 'area') this.skillAreaEffect(g, skill);
    else if (skill.targetType === 'directional') this.skillDirectionalEffect(g, skill, direction, color);
    else this.skillSelfEffect(g, skill);
    this.effectSparks(x, y, color);
    this.finishEffect(g, skill.targetType === 'self' ? 600 : 420);
  }

  private skillAreaEffect(g: Phaser.GameObjects.Graphics, skill: SkillDefinition): void {
    const radius = skill.effect.radius ?? 32;
    g.strokeCircle(0, 0, radius);
    if (skill.element === 'earth') {
      g.strokeCircle(0, 0, radius * 0.72);
      for (let index = 0; index < 12; index++) {
        const angle = index * Math.PI / 6;
        g.fillTriangle(Math.cos(angle - 0.16) * 9, Math.sin(angle - 0.16) * 9,
          Math.cos(angle) * 30, Math.sin(angle) * 30,
          Math.cos(angle + 0.16) * 9, Math.sin(angle + 0.16) * 9);
        g.beginPath();
        g.moveTo(Math.cos(angle) * radius * 0.4, Math.sin(angle) * radius * 0.4);
        g.lineTo(Math.cos(angle + 0.08) * radius * 0.65, Math.sin(angle + 0.08) * radius * 0.65);
        g.lineTo(Math.cos(angle) * (radius - 2), Math.sin(angle) * (radius - 2));
        g.strokePath();
      }
    } else if (skill.element === 'flame') {
      g.fillCircle(0, 0, 18);
      for (let index = 0; index < 12; index++) {
        const angle = index * Math.PI / 6;
        g.fillTriangle(Math.cos(angle - 0.12) * radius * 0.3, Math.sin(angle - 0.12) * radius * 0.3,
          Math.cos(angle) * (radius - 2), Math.sin(angle) * (radius - 2),
          Math.cos(angle + 0.12) * radius * 0.3, Math.sin(angle + 0.12) * radius * 0.3);
      }
    } else if (skill.element === 'water') {
      g.beginPath();
      for (let index = 0; index <= 48; index++) {
        const angle = index * Math.PI / 12;
        const distance = radius * (0.12 + index / 48 * 0.82);
        if (index === 0) g.moveTo(Math.cos(angle) * distance, Math.sin(angle) * distance);
        else g.lineTo(Math.cos(angle) * distance, Math.sin(angle) * distance);
      }
      g.strokePath();
    } else {
      for (let index = 0; index < 3; index++) {
        g.beginPath();
        g.arc(0, 0, radius * (0.45 + index * 0.24), index * 2.1, index * 2.1 + 4.3, false);
        g.strokePath();
      }
    }
  }

  private skillDirectionalEffect(g: Phaser.GameObjects.Graphics, skill: SkillDefinition, direction: Phaser.Math.Vector2, color: number): void {
    const range = skill.effect.range ?? 100;
    g.setRotation(Math.atan2(direction.y, direction.x));
    g.lineStyle(1, color, 0.3);
    g.strokeRect(0, -32, range, 64);
    g.lineStyle(2, color, 0.75);
    g.lineBetween(0, 0, range, 0);
    g.strokeCircle(range, 0, 3);
    if (skill.id === 'mountain-cleave') {
      g.beginPath();
      g.moveTo(0, 0);
      for (let index = 1; index <= 8; index++) g.lineTo(range * index / 8, index === 8 ? 0 : (index % 2 ? -8 : 8));
      g.strokePath();
    } else if (skill.id === 'flame-beam') {
      g.fillTriangle(0, -12, range, 0, 0, 12);
      g.fillStyle(0xffdf88, 0.8);
      g.fillTriangle(range * 0.2, -4, range, 0, range * 0.2, 4);
    } else if (skill.id === 'blazing-dash') {
      for (let index = 0; index < 5; index++) {
        const distance = range * index / 5;
        g.fillTriangle(distance, -8, distance + range / 5, 0, distance, 8);
      }
    } else if (skill.id === 'tidal-surge') {
      for (let index = 1; index <= 3; index++) {
        g.beginPath();
        g.arc(range * index / 4, 0, 18, -Math.PI / 2, Math.PI / 2, false);
        g.strokePath();
      }
    } else if (skill.id === 'spear-thrust') {
      g.lineStyle(6, color, 0.75);
      g.lineBetween(0, 0, range * 0.75, 0);
      g.fillTriangle(range * 0.7, -7, range, 0, range * 0.7, 7);
    } else if (skill.id === 'lac-blade-dance') {
      for (let index = 0; index < 3; index++) {
        g.beginPath();
        g.arc(range * (0.2 + index * 0.22), 0, range * 0.25, -1.2, 1.2, false);
        g.strokePath();
      }
    }
  }

  private skillSelfEffect(g: Phaser.GameObjects.Graphics, skill: SkillDefinition): void {
    if (skill.id === 'stone-armor') {
      g.strokeCircle(0, 0, 30);
      for (let index = 0; index < 6; index++) {
        const angle = index * Math.PI / 3;
        g.fillRect(Math.cos(angle) * 23 - 5, Math.sin(angle) * 23 - 7, 10, 14);
      }
    } else {
      g.strokeCircle(0, 0, 32);
      g.strokeCircle(0, 0, 22);
      g.lineStyle(4, 0xb9f5e1, 0.95);
      g.lineBetween(-8, 0, 8, 0);
      g.lineBetween(0, -8, 0, 8);
    }
  }

  private effectSparks(x: number, y: number, color: number): void {
    for (let index = 0; index < graphicsSettings.getBudget().combatSparks; index++) {
      const angle = index * 2.4;
      const spark = this.scene.add.rectangle(x, y, 3, 2, color, 0.8).setDepth(901);
      this.scene.tweens.add({ targets: spark, x: x + Math.cos(angle) * (12 + index * 2),
        y: y + Math.sin(angle) * (12 + index * 2), alpha: 0, duration: 160 });
      this.finishEffect(spark, 160, false);
    }
  }

  private finishEffect(effect: Phaser.GameObjects.Graphics | Phaser.GameObjects.Rectangle, duration: number, fade = true): void {
    let timer: Phaser.Time.TimerEvent | undefined;
    const dispose = () => {
      this.scene.events?.off('shutdown', dispose);
      timer?.remove(false);
      this.scene.tweens.killTweensOf?.(effect);
      effect.destroy();
    };
    this.scene.events?.once('shutdown', dispose);
    if (this.scene.time) timer = this.scene.time.delayedCall(duration, dispose);
    if (fade && graphicsSettings.getBudget().combatSparks > 0) {
      this.scene.tweens.add({ targets: effect, alpha: 0, duration, onComplete: dispose });
    }
  }
}
import Phaser from 'phaser';
import { BALANCE, PALETTE, UI_DEPTH } from '../../data/config';
import { gameState, getPlayerStats } from '../systems/GameState';
import { label } from './art';
import { getChapterWorldConfig } from '../world/ChapterWorld';

export class Hud {
  private health: Phaser.GameObjects.Rectangle;
  private mana: Phaser.GameObjects.Rectangle;
  private statLabel: Phaser.GameObjects.Text;
  private questLabel: Phaser.GameObjects.Text;
  private zone: Phaser.GameObjects.Text;
  private healthLabel: Phaser.GameObjects.Text;
  private manaLabel: Phaser.GameObjects.Text;

  constructor(scene: Phaser.Scene, place: string) {
    const panel = scene.add.rectangle(195, 35, 360, 69, 0x102b27, 0.90)
      .setStrokeStyle(2, PALETTE.bronze).setDepth(UI_DEPTH);
    scene.add.rectangle(194, 24, 265, 14, 0x352e2b).setDepth(UI_DEPTH + 1);
    scene.add.rectangle(194, 47, 265, 12, 0x29333d).setDepth(UI_DEPTH + 1);
    this.health = scene.add.rectangle(61, 24, 265, 12, PALETTE.red)
      .setOrigin(0, 0.5).setDepth(UI_DEPTH + 2);
    this.mana = scene.add.rectangle(61, 47, 265, 10, PALETTE.blue)
      .setOrigin(0, 0.5).setDepth(UI_DEPTH + 2);
    this.healthLabel = label(scene, 70, 24, '', 11, '#fff3d6').setDepth(UI_DEPTH + 3);
    this.manaLabel = label(scene, 70, 47, '', 11, '#fff3d6').setDepth(UI_DEPTH + 3);
    this.statLabel = label(scene, 346, 35, '', 12, '#f8ebc8').setOrigin(0.5)
      .setDepth(UI_DEPTH + 3);
    const questPanel = scene.add.rectangle(678, 35, 546, 69, 0x102b27, 0.90)
      .setStrokeStyle(2, PALETTE.bronze).setDepth(UI_DEPTH);
    this.questLabel = label(scene, 421, 26, '', 14, '#f9e9bf')
      .setDepth(UI_DEPTH + 2);
    this.zone = label(scene, 421, 49, place, 12, '#a3c9a8')
      .setDepth(UI_DEPTH + 2);
    panel.setAlpha(0.96);
    questPanel.setAlpha(0.96);
    this.health.setScale(1, 1);
    this.mana.setScale(1, 1);
    this.refresh();
  }

  refresh(): void {
    const s = gameState.data;
    const world = getChapterWorldConfig(s.chapter);
    const caps = getPlayerStats(s);
    this.health.setScale(Math.max(0, Math.min(1, s.hp / caps.maxHp)), 1);
    this.mana.setScale(Math.max(0, Math.min(1, s.mp / caps.maxMp)), 1);
    this.healthLabel.setText(`HUYẾT ${Math.ceil(s.hp)}/${caps.maxHp}`);
    this.manaLabel.setText(`LINH ${Math.ceil(s.mp)}/${caps.maxMp}`);
    this.statLabel.setText(`Lv.${s.level}\n${s.gold} đồng`);
    const msg = s.quest === 'new' ? 'Gặp trưởng làng để nhận nhiệm vụ' :
      s.quest === 'active' ? `Săn quái: ${Math.min(s.kills, BALANCE.requiredKills)}/${BALANCE.requiredKills} | Boss: ${s.bossDead ? 'đã hạ' : 'chưa hạ'}` :
      s.quest === 'return' ? 'Đã hạ ' + world.bossName + '! Về báo trưởng làng' : 'Nhiệm vụ hoàn thành!';
    this.questLabel.setText(msg);
  }
}

export function toast(scene: Phaser.Scene, text: string, color = '#f9e9bd'): void {
  const previous = scene.children.getByName('status-toast');
  if (previous) {
    scene.tweens.killTweensOf(previous);
    previous.destroy();
  }
  const panel = scene.add.rectangle(480, 128, Math.min(720, Math.max(240, text.length * 10)), 38, 0x17342e, 0.95)
    .setStrokeStyle(1, PALETTE.bronze).setDepth(UI_DEPTH + 10);
  const textObj = label(scene, 480, 128, text, 16, color, 'center')
    .setDepth(UI_DEPTH + 11);
  const notice = scene.add.container(0, 0, [panel, textObj]).setName('status-toast').setDepth(UI_DEPTH + 10);
  scene.tweens.add({ targets: notice, alpha: 0, delay: 2000,
    duration: 400, onComplete: () => notice.destroy(true) });
}
