      this.windup = false;
      this.rangedWindup = false;
      this.chargeRemainingMs = 0;
      this.view.setAlpha(1);
      this.warning.setVisible(false);
    }
    if (status === 'slow') this.slowRemainingMs = Math.max(this.slowRemainingMs, duration);
    if (status === 'burn') {
